//! Where an OS file's bytes come from: a host file, generated bytes, or a
//! file of another ext2 volume.

use std::path::PathBuf;

use ext2fs::Ext2;

use super::volume_error;

/// Where a file's bytes come from.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Source {
    Path(PathBuf),
    Bytes(Vec<u8>),
    /// A file of another ext2 volume, read when it is written: how
    /// `lazyos-install` copies the stick's OS volume without holding it all
    /// in memory (docs/grub-install-plan.md decision 5).
    Volume(VolumeFile),
}

/// `path` on `volume`, for [`Source::Volume`].
#[derive(Clone)]
pub struct VolumeFile {
    pub volume: std::sync::Arc<Ext2>,
    pub path: String,
}

impl PartialEq for VolumeFile {
    fn eq(&self, other: &VolumeFile) -> bool {
        std::sync::Arc::ptr_eq(&self.volume, &other.volume) && self.path == other.path
    }
}

impl Eq for VolumeFile {}

impl std::fmt::Debug for VolumeFile {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "VolumeFile({})", self.path)
    }
}

impl Source {
    /// The bytes; `what` names the file in errors.
    pub fn read(&self, what: &str) -> Result<Vec<u8>, String> {
        match self {
            Source::Bytes(bytes) => Ok(bytes.clone()),
            Source::Path(path) => {
                std::fs::read(path).map_err(|e| format!("read {} for {what}: {e}", path.display()))
            }
            Source::Volume(file) => file
                .volume
                .read_file(&file.path)
                .map_err(|e| volume_error(&format!("read {} for {what}", file.path), e)),
        }
    }

    /// The length in bytes, without reading the file where that is possible.
    pub fn len(&self) -> Result<u64, String> {
        match self {
            Source::Bytes(bytes) => Ok(bytes.len() as u64),
            Source::Path(path) => std::fs::metadata(path)
                .map(|meta| meta.len())
                .map_err(|e| format!("{}: {e}", path.display())),
            Source::Volume(file) => file
                .volume
                .lookup(&file.path)
                .map(|meta| meta.size)
                .map_err(|e| volume_error(&format!("stat {}", file.path), e)),
        }
    }
}
